from pathlib import Path
from html import escape
import json
out=Path(__file__).resolve().parent

def diagram(title,desc,nodes,edges,width,height):
 s=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} {height}" role="img" aria-labelledby="t d"><title id="t">{escape(title)}</title><desc id="d">{escape(desc)}</desc><defs><marker id="arrow" markerWidth="9" markerHeight="9" refX="8" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="none" stroke="#698477" stroke-width="1.4"/></marker></defs><rect width="100%" height="100%" fill="#f7f4ea"/>']
 for a,b,label in edges:
  ax,ay,_,_,_=nodes[a]; bx,by,_,_,_=nodes[b]
  x1,y1=ax+145,ay+100;x2,y2=bx+145,by
  if by<=ay:
   x1,y1=ax+290,ay+50;x2,y2=bx+290,by+50
   line=f'M{x1} {y1} H{max(x1,x2)+30} V{y2} H{x2}'
   lx,ly=max(x1,x2)+34,(y1+y2)/2
  else:
   mid=(y1+y2)/2;line=f'M{x1} {y1} V{mid} H{x2} V{y2}';lx,ly=(x1+x2)/2,mid-9
  s.append(f'<path d="{line}" fill="none" stroke="#698477" stroke-width="2" marker-end="url(#arrow)"/>')
  if label:s.append(f'<text x="{lx}" y="{ly}" font-family="Arial,sans-serif" font-size="15" text-anchor="middle" fill="#365247" paint-order="stroke" stroke="#f7f4ea" stroke-width="5">{escape(label)}</text>')
 for key,(x,y,title,sub,status) in nodes.items():
  fill,stroke=('#e2ece2','#4c6d59') if status=='exists' else ('#fff8e9','#967746') if status=='proposed' else ('#fffdf7','#8c9f8e')
  dash=' stroke-dasharray="6 5"' if status=='proposed' else ''
  s.append(f'<g><rect x="{x}" y="{y}" width="290" height="100" rx="17" fill="{fill}" stroke="{stroke}" stroke-width="1.5"{dash}/><text x="{x+18}" y="{y+22}" font-family="Arial,sans-serif" font-size="11" letter-spacing="1.5" fill="{stroke}">{escape(status.upper())}</text><text x="{x+18}" y="{y+51}" font-family="Georgia,serif" font-size="21" fill="#254639">{escape(title)}</text><text x="{x+18}" y="{y+78}" font-family="Arial,sans-serif" font-size="14" fill="#4b5c50">{escape(sub)}</text></g>')
 result=''.join(s)+'</svg>'
 prefix=title.lower().replace(' ','-')
 return result.replace('id="t"',f'id="{prefix}-t"').replace('id="d"',f'id="{prefix}-d"').replace('aria-labelledby="t d"',f'aria-labelledby="{prefix}-t {prefix}-d"').replace('id="arrow"',f'id="{prefix}-arrow"').replace('url(#arrow)',f'url(#{prefix}-arrow)')
